#!/usr/bin/env python3
"""
environmentalNODE — ROS2 Jazzy version
Subscribes to /automobile/environment and forwards data to EnvironmentalHandler.
"""

import time
import threading
from multiprocessing import Pipe

import rclpy
from rclpy.node import Node
from utils.msg import Environmental  # was: environmental

from environmental import EnvironmentalHandler


class EnvironmentalNode(Node):
    def __init__(self):
        super().__init__('environmentalNODE')

        beacon          = 23456
        id_             = 106
        server_pubkey   = '/home/pi/dei_ws/src/output/src/environmentalserver/publickey_server.pem'
        client_privkey  = '/home/pi/dei_ws/src/output/src/environmentalserver/privatekey_client.pem'

        gpsStR, self._pipe_send = Pipe(duplex=False)

        self._env_handler = EnvironmentalHandler(
            id_, beacon, server_pubkey, gpsStR, client_privkey
        )
        self._env_handler.start()
        time.sleep(5)

        self.create_subscription(
            Environmental,
            '/automobile/environment',
            self._send_cb,
            10,
        )
        self.get_logger().info("environmentalNODE started")

    def _send_cb(self, msg: Environmental):
        self._pipe_send.send({
            "obstacle_id": msg.obstacle_id,
            "x": msg.x,
            "y": msg.y,
        })

    def destroy_node(self):
        self._env_handler.stop()
        self._env_handler.join()
        super().destroy_node()


def main(args=None):
    rclpy.init(args=args)
    node = EnvironmentalNode()
    try:
        rclpy.spin(node)
    except KeyboardInterrupt:
        pass
    finally:
        node.destroy_node()
        rclpy.shutdown()


if __name__ == '__main__':
    main()
